import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, transaction } from './db.ts';
import { getJobRow, toJob, type JobRow } from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** The worker counts as up if its heartbeat is at most this old. */
const WORKER_STALE_MS = 3_000;
/** Largest request body accepted. Input is at most 1000 characters, so this is generous. */
const MAX_BODY_BYTES = 64 * 1024;
const JSON_CONTENT_TYPE = /^application\/json(\s*;.*)?$/i;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_INPUT_LENGTH = 1000;

interface FieldError {
  field: string;
  message: string;
}

class ApiError extends Error {
  status: number;
  code: string;
  fields: FieldError[] | undefined;
  allow: string | undefined;

  constructor(status: number, code: string, message: string, fields?: FieldError[], allow?: string) {
    super(message);
    this.status = status;
    this.code = code;
    this.fields = fields;
    this.allow = allow;
  }
}

function invalid(fields: FieldError[]): ApiError {
  return new ApiError(400, 'invalid_request', 'The request is invalid.', fields);
}

function methodNotAllowed(allowed: string[]): ApiError {
  return new ApiError(405, 'method_not_allowed', `Method not allowed. Use ${allowed.join(', ')}.`, undefined, allowed.join(', '));
}

function sendJson(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, err: ApiError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  sendJson(res, err.status, { error }, err.allow ? { allow: err.allow } : {});
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (tooLarge) reject(invalid([{ field: 'body', message: `Body must be at most ${MAX_BODY_BYTES} bytes.` }]));
      else resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', reject);
  });
}

interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
  key: string | undefined;
}

/** Checks the request headers and body, returning the submission with defaults applied. Throws invalid_request listing every bad field. */
function parseSubmission(req: IncomingMessage, raw: string): Submission {
  const errors: FieldError[] = [];

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'Must be 1–128 characters of letters, digits, "_" or "-".' });
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;
  const contentType = req.headers['content-type'];
  if (!contentType || !JSON_CONTENT_TYPE.test(contentType)) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else {
    let parsed: unknown;
    let parsedOk = false;
    try {
      parsed = JSON.parse(raw);
      parsedOk = true;
    } catch {
      errors.push({ field: 'body', message: 'Body must be valid JSON.' });
    }
    if (parsedOk) {
      if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        errors.push({ field: 'body', message: 'Body must be a JSON object.' });
      } else {
        const obj = parsed as Record<string, unknown>;
        const allowed = new Set(['input', 'steps', 'failAttempts']);
        for (const name of Object.keys(obj)) {
          if (!allowed.has(name)) errors.push({ field: name, message: 'Unknown field.' });
        }

        if (!('input' in obj)) {
          errors.push({ field: 'input', message: 'Required.' });
        } else if (typeof obj.input !== 'string') {
          errors.push({ field: 'input', message: 'Must be a string.' });
        } else if (obj.input.length < 1 || obj.input.length > MAX_INPUT_LENGTH) {
          errors.push({ field: 'input', message: `Must be 1–${MAX_INPUT_LENGTH} characters.` });
        } else if (obj.input.trim() === '') {
          errors.push({ field: 'input', message: 'Must not be only whitespace.' });
        } else {
          input = obj.input;
        }

        const readInt = (name: 'steps' | 'failAttempts', min: number, max: number, fallback: number): number => {
          if (!(name in obj)) return fallback;
          const value = obj[name];
          if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
            errors.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
            return fallback;
          }
          return value;
        };
        steps = readInt('steps', 1, 20, 5);
        failAttempts = readInt('failAttempts', 0, 5, 0);
      }
    }
  }

  if (errors.length > 0) throw invalid(errors);
  return { input, steps, failAttempts, key };
}

function workerUp(): boolean {
  const row = db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'").get() as { at: number } | undefined;
  return row !== undefined && Date.now() - row.at <= WORKER_STALE_MS;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const sub = parseSubmission(req, await readBody(req));
  const fingerprint = JSON.stringify([sub.input, sub.steps, sub.failAttempts]);
  const now = new Date().toISOString();

  const outcome = transaction(db, () => {
    if (sub.key !== undefined) {
      const prior = db.prepare('SELECT fingerprint, job_id FROM idempotency WHERE key = ?').get(sub.key) as
        | { fingerprint: string; job_id: string }
        | undefined;
      if (prior) {
        if (prior.fingerprint !== fingerprint) {
          throw new ApiError(409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        }
        const row = getJobRow(db, prior.job_id);
        if (!row) throw new Error(`idempotency key ${sub.key} points at missing job ${prior.job_id}`);
        return { replay: true, row };
      }
    }
    const id = randomUUID();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, result_output, error, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?)`,
    ).run(id, sub.input, sub.steps, sub.failAttempts, Date.now(), now, now);
    if (sub.key !== undefined) {
      db.prepare('INSERT INTO idempotency (key, fingerprint, job_id) VALUES (?, ?, ?)').run(sub.key, fingerprint, id);
    }
    const row = getJobRow(db, id);
    if (!row) throw new Error(`job ${id} missing right after insert`);
    return { replay: false, row };
  });

  sendJson(res, outcome.replay ? 200 : 201, toJob(outcome.row));
}

function listJobs(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  sendJson(res, 200, { jobs: rows.map(toJob) });
}

function getJob(res: ServerResponse, id: string): void {
  const row = getJobRow(db, id);
  if (!row) throw new ApiError(404, 'not_found', 'No job with that id.');
  sendJson(res, 200, toJob(row));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    sendJson(res, 200, { status: 'ok', worker: workerUp() ? 'up' : 'down' });
    return;
  }
  if (pathname === '/') {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return listJobs(res);
    if (method === 'POST') return createJob(req, res);
    throw methodNotAllowed(['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    return getJob(res, match[1]!);
  }
  throw new ApiError(404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    if (res.headersSent) {
      res.end();
      return;
    }
    if (e instanceof ApiError) {
      sendError(res, e);
      return;
    }
    console.error('unexpected error:', e);
    sendJson(res, 500, { error: { code: 'internal_error', message: 'Internal error.' } });
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    server.close();
    server.closeAllConnections();
    db.close();
    process.exit(0);
  });
}

